def lookup(words, prefix, k):
    matches = {word for word in words if word.startswith(prefix)}
    return sorted(matches)[:k]
```

The set removes exact duplicates after filtering for case-sensitive prefix matches. `sorted` then applies Python’s ordinary case-sensitive lexical order, and slicing limits the result to at most `k` words. An empty prefix matches every word; `k = 0` returns an empty list.

I’m developing a toy, nonfinancial integer counter ledger. Each group contains signed integer changes applied in order, and the balance must remain nonnegative after every change. A rejected group must leave its input unchanged and produce no partial result. Workshop planning currently assumes 6 demonstration groups, 8 printed ledger sheets per group, and 29 sheets in stock.

```python
def apply_group(ledger, changes):
    for delta in changes:
        ledger['balance'] += delta
        if ledger['balance'] < 0:
            return False
    return True
```

Trace this function with an initial balance of 5 and changes `[3, -10, 4]`. Show what survives the failure and explain why the final sum does not excuse an intermediate underflow.

The implementation below accepts a dictionary and a list or tuple of two-element list or tuple changes. It validates the entire group before checking for underflow, as specified.

```python
def apply_group(counters, changes):
    if not isinstance(counters, dict):
        raise TypeError('counters must be a dictionary')
    if not isinstance(changes, (list, tuple)):
        raise TypeError('changes must be a list or tuple')

    for name, balance in counters.items():
        if not isinstance(name, str) or type(balance) is not int:
            raise TypeError('counter names must be strings and balances integers')
        if balance < 0:
            raise ValueError('starting balance must be nonnegative')

    for change in changes:
        if not isinstance(change, (list, tuple)) or len(change) != 2:
            raise TypeError('each change must be a pair')
        name, delta = change
        if not isinstance(name, str) or type(delta) is not int:
            raise TypeError('names must be strings and deltas integers')
        if name not in counters:
            raise KeyError(name)

    result = counters.copy()
    for name, delta in changes:
        result[name] += delta
        if result[name] < 0:
            return None
    return result
```

For `{'a': 2, 'b': 1}` with `[('a', 3), ('b', -2)]`, the temporary values become `a = 5`, then `b = -1`. The group returns `None`; the original stays `{'a': 2, 'b': 1}`.

```python
from copy import deepcopy


def raises(exception, fn, *args):
    try:
        fn(*args)
    except exception:
        return
    raise AssertionError(f'Expected {exception.__name__}')


original = {'a': 2, 'b': 1}
changes = [('a', 3), ('b', -2)]
before = deepcopy((original, changes))
assert apply_group(original, changes) is None
assert (original, changes) == before

result = apply_group(original, [('a', -2), ('b', 3)])
assert result == {'a': 0, 'b': 4} and result is not original
assert original == before[0]
empty = apply_group(original, [])
assert empty == original and empty is not original

# Validation takes precedence over an earlier underflow.
raises(KeyError, apply_group, original, [('a', -3), ('missing', 1)])
raises(TypeError, apply_group, original, [('a', -3), ('b', True)])
raises(TypeError, apply_group, original, [('a',)])
raises(TypeError, apply_group, {'a': True}, [])
raises(ValueError, apply_group, {'a': -1}, [])
assert (original, changes) == before
```
